\copy (WITH vehicle_cluster_counts AS (SELECT tenant_id, vehicle_id, kv.key::bigint AS cluster_id, kv.value::int AS images FROM vehicle_cluster_history CROSS JOIN LATERAL jsonb_each_text(cluster_counts) AS kv(key, value) WHERE week_start = '2026-11-02') SELECT vcc.tenant_id, vcc.vehicle_id, cd.driver_id, SUM(vcc.images) AS images FROM vehicle_cluster_counts vcc JOIN cluster_details cd ON cd.cluster_id = vcc.cluster_id WHERE cd.driver_id > 0 GROUP BY vcc.tenant_id, vcc.vehicle_id, cd.driver_id) TO '/Users/swapnilmane/NetraDyne/driver_history_use/data/AN-37740/step_2/an37740_candidate_drivers.csv' WITH CSV HEADER;
